{"content": "///|
/// TOML parser library.
/// Parses a subset of TOML into deterministic JSON.

///|
suberror ParseError {
  /// Unexpected character at the given position.
  UnexpectedChar(line : Int, col : Int, got : Char)
  /// Unterminated string (no closing quote before end-of-line/file).
  UnterminatedString(line : Int)
  /// Invalid escape sequence inside a string.
  InvalidEscape(line : Int, col : Int, ch : Char)
  /// A value was expected but not found.
  ExpectedValue(line : Int, col : Int)
  /// A duplicate key was detected.
  DuplicateKey(key : String)
} derive(Debug, Show)

///|
/// Parse TOML text into a `Json` value.
/// Returns a `Json::Object` on success or raises `ParseError` on invalid input.
pub fn parse(text : String) -> Json raise ParseError {
  let lines = text.split("\n").to_array()
  let state : State = { root: Json::object(Map::new()), current_path: [] }
  let line_num = 0

  for i = 0; i < lines.length(); i = i + 1 {
    let raw = lines[i]
    let trimmed = raw.trim()
    let line_num = i + 1

    // skip blank lines and comments
    if trimmed.is_empty() || trimmed.starts_with("#") {
      continue
    }

    // table header: [table.name]
    if trimmed.starts_with("[") {
      if trimmed.ends_with("]") == false {
        raise ParseError::UnexpectedChar(line=line_num, col=1, got='[')
      }
      let inner = trimmed.sub(start=1, end=trimmed.length() - 1).trim().to_owned()
      let key_parts = split_key(inner)
      state.current_path = key_parts
      continue
    }

    // key-value pair
    let eq_pos = find_eq(trimmed)
    match eq_pos {
      None => raise ParseError::ExpectedValue(line=line_num, col=1)
      Some(pos) => {
        let key_str = trimmed.sub(start=0, end=pos).trim().to_owned()
        let val_str = trimmed.sub(start=pos + 1, end=trimmed.length()).trim().to_owned()

        // handle comment on the value side
        let val_parts = val_str.split("#").to_array()
        let val_text = val_parts[0].trim().to_owned()

        let key_parts = split_key(key_str)
        let full_path = state.current_path + key_parts
        let value = parse_value(val_text, line_num)

        set_nested(&state.root, full_path, value)
      }
    }
  }

  state.root
}

///|
/// Internal parser state.
struct State {
  root : Json
  current_path : Array[String]
}

///|
/// Split a dotted key like "a.b.c" into ["a", "b", "c"].
fn split_key(s : String) -> Array[String] {
  if s.is_empty() {
    return []
  }
  // Handle bare keys: split on dots, trim each part.
  // Also handle quoted keys: "key" or 'key' (but we only handle bare keys and "." for now).
  let parts = s.split(".")
  let mut result : Array[String] = []
  for part in parts {
    let trimmed = part.trim().to_owned()
    if trimmed.is_empty() == false {
      result.push(trimmed)
    }
  }
  result
}

///|
/// Find the position of '=' in a line, respecting that '=' inside strings
/// should not count.
fn find_eq(s : String) -> Option[Int] {
  let mut i = 0
  let mut in_string = false
  let mut string_char : Char = '"'
  while i < s.length() {
    let ch = s.get_char(i)
    match ch {
      None => break
      Some(c) => {
        if in_string {
          if c == string_char {
            // check for escaped quote
            if i > 0 {
              let prev = s.get_char(i - 1)
              match prev {
                Some(p) => {
                  if p != '\\' {
                    in_string = false
                  }
                }
                None => in_string = false
              }
            } else {
              in_string = false
            }
          }
        } else {
          if c == '"' || c == '\'' {
            in_string = true
            string_char = c
          } else if c == '=' {
            return Some(i)
          }
        }
        i = i + c.len_utf8()
      }
    }
  }
  None
}

///|
/// Parse a value string (right-hand side of "=") into a Json value.
fn parse_value(s : String, line : Int) -> Json raise ParseError {
  if s.is_empty() {
    raise ParseError::ExpectedValue(line=line, col=1)
  }

  // boolean
  if s == "true" {
    return Json::boolean(true)
  }
  if s == "false" {
    return Json::boolean(false)
  }

  // array
  if s.starts_with("[") {
    return parse_array(s, line)
  }

  // string
  if s.starts_with("\"") || s.starts_with("'") {
    return parse_string(s, line)
  }

  // integer (including negative)
  return parse_integer(s, line)
}

///|
/// Parse an integer value.
fn parse_integer(s : String, line : Int) -> Json raise ParseError {
  // Allow leading minus
  let mut start = 0
  if s.starts_with("-") {
    start = 1
  }
  let mut i = start
  while i < s.length() {
    let ch = s.get_char(i)
    match ch {
      None => break
      Some(c) => {
        if c >= '0' && c <= '9' {
          // ok
        } else if c == '_' {
          // underscore in numbers, skip
        } else if c == '#' {
          // comment start — this shouldn't happen since we strip comments earlier
          break
        } else {
          raise ParseError::UnexpectedChar(line=line, col=i + 1, got=c)
        }
        i = i + c.len_utf8()
      }
    }
  }
  let cleaned = s.sub(start=0, end=i).to_owned().replace("_", "")
  let n : Int = @string.from_str(cleaned) catch {
    _ => raise ParseError::UnexpectedChar(line=line, col=1, got=s.get_char(0).unwrap_or(' '))
  }
  Json::number(n.to_double(), repr=cleaned)
}

///|
/// Parse a string value, handling escape sequences.
fn parse_string(s : String, line : Int) -> Json raise ParseError {
  if s.is_empty() {
    raise ParseError::UnterminatedString(line=line)
  }
  let quote = s.get_char(0).unwrap_or('"')
  if quote != '"' && quote != '\'' {
    raise ParseError::UnexpectedChar(line=line, col=1, got=quote)
  }

  // Find the closing quote
  let chars = s.to_array()
  let mut result = StringBuilder::new()
  let mut i = 1
  while i < chars.length() {
    let c = chars[i]
    if c == '\\' && quote == '"' {
      // escape sequence in double-quoted strings
      i = i + 1
      if i >= chars.length() {
        raise ParseError::UnterminatedString(line=line)
      }
      let esc = chars[i]
      match esc {
        '"' => result.write_char('"')
        '\\' => result.write_char('\\')
        'n' => result.write_char('\n')
        't' => result.write_char('\t')
        'r' => result.write_char('\r')
        _ => raise ParseError::InvalidEscape(line=line, col=i + 1, ch=esc)
      }
    } else if c == quote {
      // closing quote — check it's not escaped
      if i > 0 && chars[i - 1] == '\\' && quote == '"' {
        result.write_char(quote)
      } else {
        return Json::string(result.to_owned())
      }
    } else {
      result.write_char(c)
    }
    i = i + 1
  }

  // If we get here, we never found the closing quote
  raise ParseError::UnterminatedString(line=line)
}

///|
/// Parse an array of values.
fn parse_array(s : String, line : Int) -> Json raise ParseError {
  if s.starts_with("[") == false || s.ends_with("]") == false {
    raise ParseError::UnexpectedChar(line=line, col=1, got=s.get_char(0).unwrap_or(' '))
  }

  let inner = s.sub(start=1, end=s.length() - 1).trim().to_owned()
  let mut result = Json::array([])
  if inner.is_empty() {
    return result
  }

  // Split by commas, but respect nested structures
  let elements = split_array_elements(inner)
  for elem in elements {
    let trimmed = elem.trim().to_owned()
    if trimmed.is_empty() == false {
      let val = parse_value(trimmed, line)
      match result {
        Json::Array(arr) => arr.push(val)
        _ => ()
      }
    }
  }
  result
}

///|
/// Split array elements by commas, respecting nested brackets and strings.
fn split_array_elements(s : String) -> Array[String] {
  let mut result : Array[String] = []
  let mut depth = 0
  let mut in_string = false
  let mut string_char : Char = '"'
  let mut start = 0
  let mut i = 0
  while i < s.length() {
    let ch = s.get_char(i)
    match ch {
      None => break
      Some(c) => {
        if in_string {
          if c == string_char && (i == 0 || s.get_char(i - 1).unwrap_or(' ') != '\\') {
            in_string = false
          }
        } else {
          if c == '"' || c == '\'' {
            in_string = true
            string_char = c
          } else if c == '[' {
            depth = depth + 1
          } else if c == ']' {
            depth = depth - 1
          } else if c == ',' && depth == 0 {
            result.push(s.sub(start=start, end=i).to_owned())
            start = i + 1
          }
        }
        i = i + c.len_utf8()
      }
    }
  }
  // last element
  if start < s.length() {
    result.push(s.sub(start=start, end=s.length()).to_owned())
  }
  result
}

///|
/// Set a value at a dotted path in the JSON object, checking for duplicate keys.
fn set_nested(root : Json, path : Array[String], value : Json) raise ParseError {
  if path.is_empty() {
    return
  }

  match root {
    Json::Object(map) => {
      let key = path[0]
      if path.length() == 1 {
        // leaf — check for duplicate
        if map.contains(key) {
          raise ParseError::DuplicateKey(key=key)
        }
        map[key] = value
      } else {
        // intermediate — create or navigate into existing table
        let child = if map.contains(key) {
          map[key]
        } else {
          let new_obj = Json::object(Map::new())
          map[key] = new_obj
          new_obj
        }
        let rest = path[1:]
        set_nested(child, rest, value)
      }
    }
    _ => raise ParseError::DuplicateKey(key=path[0])
  }
}
