{"content": "///|
/// CLI: tomljson — parse TOML files or stdin and print JSON.
/// Usage:
///   tomljson <file>          parse a TOML file
///   tomljson --stdin         read TOML from stdin

struct Config {
  input : String
  stdin : Bool
}

///|
async fn main {
  let matches = @argparse.parse(
    Command(
      "tomljson",
      about="Parse TOML and print JSON.",
      flags=[
        FlagArg("stdin", long="stdin", about="Read TOML from stdin instead of a file."),
      ],
      positionals=[
        PositionArg("input", default_values=["-"], about="TOML file path. Use '-' for stdin (implies --stdin)."),
      ],
    ),
  )

  let config = match matches {
    {
      values: { "input"? : Some([input, ..]), .. },
      flags: { "stdin"? : Some(stdin_flag), .. },
      ..,
    } => {
      let stdin = stdin_flag || input == "-"
      { input, stdin }
    }
    {
      values: { "input"? : Some([input, ..]), .. },
      flags: { "stdin"? : None, .. },
      ..,
    } => {
      let stdin = input == "-"
      { input, stdin }
    }
    _ => fail("missing required argument: input")
  }

  let text = if config.stdin {
    @stdio.stdin.read_all().text()
  } else {
    @fs.read_file(config.input).text()
  }

  let json = @toml.parse(text) catch {
    err => {
      let msg = match err {
        @toml.ParseError::DuplicateKey(key) => ($|Error: duplicate key "\{key}"\n)
        @toml.ParseError::UnexpectedChar(line, col, got) =>
          ($|Error at line \{line}, col \{col}: unexpected character '\{got}'\n)
        @toml.ParseError::UnterminatedString(line) =>
          ($|Error at line \{line}: unterminated string\n)
        @toml.ParseError::InvalidEscape(line, col, ch) =>
          ($|Error at line \{line}, col \{col}: invalid escape '\\\{ch}'\n)
        @toml.ParseError::ExpectedValue(line, col) =>
          ($|Error at line \{line}, col \{col}: expected value\n)
      }
      @stdio.stderr.write_string(msg)
      return
    }
  }

  println(json.stringify())
}
