{"content": "///|
/// CLI: tomljson — parse TOML files or stdin and print JSON.

struct Config {
  input : String
  stdin : Bool
}

///|
async fn main {
  let matches = @argparse.parse(
    Command(
      "tomljson",
      about="Parse TOML and print JSON.",
      flags=[
        FlagArg("stdin", long="stdin", about="Read TOML from stdin instead of a file."),
      ],
      positionals=[
        PositionArg("input", default_values=["-"], about="TOML file path."),
      ],
    ),
  )

  let config = match matches {
    {
      values: { "input"? : Some([input, ..]), .. },
      flags: { "stdin"? : Some(stdin_flag), .. },
      ..,
    } => {
      let stdin = stdin_flag || input == "-"
      { input, stdin }
    }
    {
      values: { "input"? : Some([input, ..]), .. },
      flags: { "stdin"? : None, .. },
      ..,
    } => {
      let stdin = input == "-"
      { input, stdin }
    }
    _ => fail("missing required argument: input")
  }

  let text = if config.stdin {
    @stdio.stdin.read_all().text()
  } else {
    @fs.read_file(config.input).text()
  }

  let json = @toml.parse(text) catch {
    err => {
      @stdio.stderr.write(@toml.error_message(err))
      return
    }
  }

  println(json.stringify())
}
