{"content": "///|
/// Black-box tests for the TOML parser.

///|
/// Simple key-value pair.
test "simple key-value" {
  let json = @toml.parse("key = 42")
  match json {
    Json::Object(map) => {
      assert_eq!(map.contains("key"), true)
      let val = map["key"]
      match val {
        Json::Number(n, repr) => {
          assert_eq!(repr, "42")
          assert_eq!(n.to_int(), 42)
        }
        _ => fail!("expected number")
      }
    }
    _ => fail!("expected object")
  }
}

///|
/// Boolean values.
test "boolean values" {
  let json = @toml.parse("a = true\nb = false")
  match json {
    Json::Object(map) => {
      assert_eq!(map["a"], Json::boolean(true))
      assert_eq!(map["b"], Json::boolean(false))
    }
    _ => fail!("expected object")
  }
}

///|
/// String values with escapes.
test "string values" {
  let json = @toml.parse("name = \"hello\\nworld\"")
  match json {
    Json::Object(map) => {
      let val = map["name"]
      match val {
        Json::String(s) => assert_eq!(s, "hello\nworld")
        _ => fail!("expected string")
      }
    }
    _ => fail!("expected object")
  }
}

///|
/// Comments and blank lines.
test "comments and blank lines" {
  let json = @toml.parse("# this is a comment\n\nkey = 1\n# another comment")
  match json {
    Json::Object(map) => {
      assert_eq!(map.contains("key"), true)
    }
    _ => fail!("expected object")
  }
}

///|
/// Dotted keys.
test "dotted keys" {
  let json = @toml.parse("a.b.c = 1")
  match json {
    Json::Object(map) => {
      assert_eq!(map.contains("a"), true)
      match map["a"] {
        Json::Object(inner) => {
          assert_eq!(inner.contains("b"), true)
          match inner["b"] {
            Json::Object(inner2) => {
              assert_eq!(inner2.contains("c"), true)
              match inner2["c"] {
                Json::Number(n, repr) => assert_eq!(repr, "1")
                _ => fail!("expected number")
              }
            }
            _ => fail!("expected object")
          }
        }
        _ => fail!("expected object")
      }
    }
    _ => fail!("expected object")
  }
}

///|
/// Table headers.
test "table headers" {
  let json = @toml.parse("[owner]\nname = \"Alice\"")
  match json {
    Json::Object(map) => {
      assert_eq!(map.contains("owner"), true)
      match map["owner"] {
        Json::Object(owner) => {
          assert_eq!(owner.contains("name"), true)
          match owner["name"] {
            Json::String(s) => assert_eq!(s, "Alice")
            _ => fail!("expected string")
          }
        }
        _ => fail!("expected object")
      }
    }
    _ => fail!("expected object")
  }
}

///|
/// Nested tables.
test "nested tables" {
  let json = @toml.parse("[database.settings]\nhost = \"localhost\"\nport = 5432")
  match json {
    Json::Object(map) => {
      assert_eq!(map.contains("database"), true)
      match map["database"] {
        Json::Object(db) => {
          assert_eq!(db.contains("settings"), true)
          match db["settings"] {
            Json::Object(settings) => {
              assert_eq!(settings.contains("host"), true)
              assert_eq!(settings.contains("port"), true)
            }
            _ => fail!("expected object")
          }
        }
        _ => fail!("expected object")
      }
    }
    _ => fail!("expected object")
  }
}

///|
/// Arrays of integers.
test "integer arrays" {
  let json = @toml.parse("nums = [1, 2, 3]")
  match json {
    Json::Object(map) => {
      assert_eq!(map.contains("nums"), true)
      match map["nums"] {
        Json::Array(arr) => {
          assert_eq!(arr.length(), 3)
        }
        _ => fail!("expected array")
      }
    }
    _ => fail!("expected object")
  }
}

///|
/// Arrays of booleans.
test "boolean arrays" {
  let json = @toml.parse("flags = [true, false, true]")
  match json {
    Json::Object(map) => {
      match map["flags"] {
        Json::Array(arr) => {
          assert_eq!(arr.length(), 3)
          assert_eq!(arr[0], Json::boolean(true))
          assert_eq!(arr[1], Json::boolean(false))
          assert_eq!(arr[2], Json::boolean(true))
        }
        _ => fail!("expected array")
      }
    }
    _ => fail!("expected object")
  }
}

///|
/// Mixed table and dotted keys.
test "table with dotted keys" {
  let json = @toml.parse("[server]\nserver.host = \"0.0.0.0\"\nserver.port = 8080")
  match json {
    Json::Object(map) => {
      assert_eq!(map.contains("server"), true)
      match map["server"] {
        Json::Object(server) => {
          assert_eq!(server.contains("host"), true)
          assert_eq!(server.contains("port"), true)
        }
        _ => fail!("expected object")
      }
    }
    _ => fail!("expected object")
  }
}

///|
/// Duplicate key should raise error.
test "duplicate key error" {
  match @toml.parse("key = 1\nkey = 2") {
    _ => fail!("expected error but got success")
  } catch {
    @toml.ParseError::DuplicateKey(key) => assert_eq!(key, "key")
    _ => fail!("expected DuplicateKey error")
  }
}
